<script setup lang="ts">
import { onUnmounted, ref, toRef } from 'vue';
import { formatTime, type Api, type AccessSession } from './types';
const props=defineProps<{session:AccessSession;api:Api;busy:boolean;mutate:(a:()=>Promise<unknown>,n:string)=>Promise<boolean>}>();
interface Credential {tokenId:string;name:string;role:string;version:number;expiresAt:string;revokedAt:string|null}
interface Audit {auditId:string;actor:string;role:string;method:string;target:string;status:number|null;createdAt:string;completedAt:string|null}
const tokens=ref<Credential[]>([]),audit=ref<Audit[]>([]),error=ref(''),loading=ref(false),page=ref(1),total=ref(0),filter=ref('');
const name=ref(''),role=ref('viewer'),days=ref(30),issued=toRef(props.session,'issued'),revealed=ref(false),pendingIssue=toRef(props.session,'pendingIssue'),revoking=ref<Credential|null>(null),confirmName=ref('');
let alive=true,g=0,c:AbortController|undefined;
async function load(){c?.abort();const control=new AbortController();c=control;const current=++g;loading.value=true;error.value='';try{const [a,b]=await Promise.all([props.api<{items:Credential[]}>('access/tokens','GET',undefined,control.signal),props.api<{items:Audit[];total:number}>(`audit?page=${page.value}${filter.value?'&role='+filter.value:''}`,'GET',undefined,control.signal)]);if(alive&&current===g){tokens.value=a.items;audit.value=b.items;total.value=b.total;}}catch(e){if(alive&&current===g&&!control.signal.aborted){tokens.value=[];audit.value=[];error.value=e instanceof Error?e.message:'读取失败';}}finally{if(alive&&current===g)loading.value=false;}}
async function issue(){if(pendingIssue.value||props.busy)return;pendingIssue.value=true;const session=props.session;const ok=await props.mutate(async()=>{const value=await props.api<{token:string}>('access/tokens','POST',{name:name.value,role:role.value,expiresAt:new Date(Date.now()+days.value*86400000).toISOString()});if(!value?.token||value.token.length<32)throw new Error('签发结果未确认');session.issued=value.token;if(alive)name.value='';},'角色令牌已签发，仅本次显示。');if(alive){if(ok)pendingIssue.value=false;await load();}}
async function revoke(){const item=revoking.value;if(!item||confirmName.value!==item.name)return;await props.mutate(()=>props.api(`access/tokens/${item.tokenId}/revoke`,'POST',{expectedVersion:item.version}),'令牌已撤销，后续请求立即失效。');if(alive){revoking.value=null;await load();}}
void load();onUnmounted(()=>{alive=false;g++;c?.abort();});
</script>
<template><section><div class="section-heading"><div><h1>权限与审计</h1><p>角色令牌与操作结果</p></div><button class="text-button" :disabled="busy||loading" @click="load">刷新权限与审计</button></div><p v-if="loading" role="status">正在读取…</p><p v-if="error" class="feedback error" role="alert">{{error}}</p>
<div v-if="issued" class="inline-form"><h2>本次角色令牌</h2><input aria-label="本次角色令牌" readonly :type="revealed?'text':'password'" :value="issued" autocomplete="off"><label class="checkbox-label spaced"><input v-model="revealed" type="checkbox">显示令牌</label><button class="text-button" @click="issued='';revealed=false">已保存，隐藏角色令牌</button></div>
<form class="inline-form spaced" @submit.prevent="issue"><h2>签发角色令牌</h2><label>名称<input v-model="name" required maxlength="80" :disabled="busy||pendingIssue"></label><div class="form-columns spaced"><label>角色<select v-model="role" :disabled="busy||pendingIssue"><option value="viewer">viewer · 只读</option><option value="operator">operator · 消息与规则</option></select></label><label>有效天数<input v-model.number="days" required type="number" min="1" max="365" :disabled="busy||pendingIssue"></label></div><p v-if="pendingIssue" role="status">签发结果未确认，不能直接重复签发；请刷新核对列表，撤销无法取得的令牌后再操作。<button type="button" class="text-button" :disabled="busy" @click="pendingIssue=false;load()">已核对，开始新的签发</button></p><div class="form-footer"><span>不会新增管理员令牌；凭据只显示一次。</span><button class="primary" :disabled="busy||loading||!!error||pendingIssue">签发令牌</button></div></form>
<div v-if="!loading&&!error" class="record-list spaced"><article v-for="t in tokens" :key="t.tokenId" class="record-card"><div class="record-heading"><h2>{{t.name}}</h2><span class="badge">{{t.role}}</span></div><p>{{t.revokedAt?'已撤销':`到期：${formatTime(t.expiresAt)}`}}</p><button class="text-button" :disabled="busy||!!t.revokedAt" @click="revoking=t;confirmName=''">撤销令牌</button></article></div>
<form v-if="revoking" class="inline-form spaced" @submit.prevent="revoke"><label>输入名称“{{revoking.name}}”确认撤销<input v-model="confirmName" :disabled="busy"></label><div class="form-footer"><button type="button" class="text-button" :disabled="busy" @click="revoking=null">取消撤销</button><button class="primary" :disabled="busy||confirmName!==revoking.name">确认撤销令牌</button></div></form>
<section class="spaced"><div class="section-heading"><h2>操作审计</h2><label>角色筛选<select v-model="filter" :disabled="loading" @change="page=1;load()"><option value="">全部</option><option v-for="r in ['admin','operator','viewer','source','anonymous']" :key="r">{{r}}</option></select></label></div><p>记录请求结果，不含令牌、消息正文或参数；未完成记录表示结果需要核对。</p><div class="table-shell"><table><thead><tr><th>时间 / 角色</th><th>操作</th><th>结果</th></tr></thead><tbody><tr v-for="a in audit" :key="a.auditId"><td>{{formatTime(a.createdAt)}}<span class="cell-sub">{{a.role}} · {{a.actor}}</span></td><td>{{a.method}}<span class="cell-sub mono">{{a.target}}</span></td><td>{{a.completedAt?a.status:'待核对'}}</td></tr></tbody></table></div><div class="pagination"><button :disabled="loading||page<=1" @click="page--;load()">上一页审计</button><span>{{page}} / {{Math.max(1,Math.ceil(total/100))}}</span><button :disabled="loading||page*100>=total" @click="page++;load()">下一页审计</button></div></section>
</section></template>
